#include "block_core.hpp"
#define main cm_original_cold_main
#include "cache_eval.cpp"
#undef main
namespace blockcold {
using namespace coldcache;
static std::vector<Config> configs(){auto out=configurations();for(auto&c:out){if(c.arm=="cache-default")c.arm="block-default";else if(c.arm=="cache-disabled")c.arm="cache-default";else if(c.arm=="binary-default")c.arm="block-binary";else if(c.arm=="binary-default-aa")c.arm="block-binary-aa";}return out;}
struct Full {Result value;cmblock::Metrics block;uint64_t bank_ns=0,loop_destroy_ns=0;bool folded=false;};
static Full calculate(const Work&w,const Config&config,const std::string&plans,bool timed){Full out;std::string method=config.arm;if(method.size()>3&&method.substr(method.size()-3)=="-aa")method.resize(method.size()-3);if(method!="block-default"&&method!="block-binary"){out.value=compute(w,config.arm,config.width,plans,timed);return out;}
 out.folded=true;auto stamp=[&](){return timed?Clock::now():Clock::time_point{};};Clock::time_point marks[6],bank_ready;marks[0]=stamp();auto&v=out.value;
 {
  auto request=JsonParser(w.request).read();require(request.at("name").str()==w.curve,"block cold identity");Fixture f(w.curve,request.at("curve"),Json{},request.at("marked"));Runtime r(f,false);auto P=point(r.group),Y=point(r.group);Affine input;require(request.at("point").at("infinity").kind==Json::Boolean,"block point encoding");input.infinity=request.at("point").at("infinity").value=="true";input.x=Big(request.at("point").at("x").str());input.y=Big(request.at("point").at("y").str());r.set(P.get(),input);require(EC_POINT_is_on_curve(r.group,P.get(),r.field.ctx)==1,"block input curve");marks[1]=stamp();
  auto plan=cmcache::deterministic(f,method=="block-binary");auto split=cmcache::decompose(r,plan);auto program=cmblock::prepare(split,plan);marks[2]=stamp();bank_ready=marks[2];
  cmblock::execute_prepared(r,Y.get(),P.get(),split,plan,program,out.block,{},[&](){bank_ready=stamp();});marks[3]=stamp();v.metrics=out.block.bank;v.bank_used=true;v.selected=plan;
  require(EC_POINT_is_on_curve(r.group,Y.get(),r.field.ctx)==1,"block output curve");v.output=encoded(r,Y.get());require(v.output==w.expected,"block symmetric expected output");marks[4]=stamp();
 }
 marks[5]=stamp();auto ns=[&](auto a,auto b){return uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(b-a).count());};v.setup=ns(marks[0],marks[1]);v.plan=ns(marks[1],marks[2]);v.arithmetic=ns(marks[2],marks[3]);v.verify=ns(marks[3],marks[4]);v.destroy=ns(marks[4],marks[5]);v.total=ns(marks[0],marks[5]);out.bank_ns=ns(marks[2],bank_ready);out.loop_destroy_ns=ns(bank_ready,marks[3]);require(v.setup+v.plan+v.arithmetic+v.verify+v.destroy==v.total&&out.bank_ns+out.loop_destroy_ns==v.arithmetic,"block complete cold ledger");return out;
}
static Json row(const Work&w,const Config&config,unsigned round,const Full&out,const std::string&digest){const auto&v=out.value;auto nullable=[&](bool known,uint64_t n){return known?number(long(n)):Json{};};return object({{"curve",text(w.curve)},{"panel",text(w.panel)},{"point",number(w.index)},{"round",number(round)},{"warmup",boolean(round==0)},{"arm",text(config.arm)},{"configuration_window",number(config.width)},{"effective_window",nullable(v.selected.width!=0,v.selected.width)},{"radix",nullable(v.selected.radix!=0,v.selected.radix)},{"offset",number(v.selected.offset)},{"setup_ns",number(long(v.setup))},{"plan_ns",number(long(v.plan))},{"arithmetic_ns",number(long(v.arithmetic))},{"verify_ns",number(long(v.verify))},{"destroy_ns",number(long(v.destroy))},{"total_ns",number(long(v.total))},{"bank_setup_ns",nullable(out.folded,out.bank_ns)},{"loop_bank_destroy_ns",nullable(out.folded,out.loop_destroy_ns)},{"planner_transitions",nullable(out.folded,out.block.planner_transitions)},{"folded_blocks",nullable(out.folded,out.block.folded_blocks)},{"folded_bits",nullable(out.folded,out.block.folded_bits)},{"leading_bits",nullable(out.folded,out.block.leading_bits)},{"group_api_counts_known",boolean(v.known)},{"doubles",nullable(v.known,v.metrics.calls.doubles)},{"adds",nullable(v.known,v.metrics.calls.adds)},{"negations",nullable(v.known,v.metrics.calls.negations)},{"table_entries",nullable(v.known,v.metrics.calls.table_points)},{"retained_bank_points",nullable(v.bank_used,v.metrics.bank_points)},{"cache_hits",nullable(v.bank_used,v.metrics.cache_hits)},{"cancelled_columns",nullable(v.bank_used,v.metrics.cancellations)},{"normalized_table_entries",nullable(v.bank_used,v.metrics.affine_entries)},{"correct",boolean(true)},{"wall_admission_pending",boolean(true)},{"output",text(v.output)},{"protocol_sha256",text(digest)}});}
static std::string frozen(const std::string&path){auto p=read_json(path),body=p;require(p.at("protocol_id").str()=="CM-BLOCK-COLD-V3"&&p.at("freeze").at("status").str()=="frozen","block cold frozen identity");body.object.erase("freeze");auto digest=p.at("freeze").at("protocol_sha256").str();require(hash(canonical_json(body))==digest,"block cold protocol digest");const auto&place=p.at("execution").at("placement");require(hash(read("/proc/self/exe"))==p.at("arms").at(size_t(0)).at("instrument").at("binary_sha256").str(),"block cold binary binding");require(place.at("configuration_count").integer()==25&&place.at("calibration_points").integer()==4&&place.at("heldout_points").integer()==8&&place.at("rounds").integer()==6&&place.at("warmups").integer()==1,"block cold finite panel");for(const auto&list:{"input_files","source_files"})for(const auto&item:place.at(list).array)require(hash(read(item.at("path").str()))==item.at("sha256").str(),"block cold file bindings");const char*env=std::getenv("CM_PROTOCOL_SHA");require(env&&std::string(env)==digest,"block inherited protocol");return digest;}
static void qualify_new(const std::string&directory,const std::string&plans){uint64_t cases=0,bad=0;for(auto&f:fixtures(directory)){Runtime r(f,true);verify_relation(r);for(long input:{0L,1L,2L,17L,-1L}){Big scalar(input),k;require(BN_nnmod(k.p,scalar.p,r.n.p,r.field.ctx),"cold qualification residue");auto P=point(r.group);require(EC_POINT_mul(r.group,P.get(),k.p,nullptr,nullptr,r.field.ctx),"cold qualification point");auto w=supplied(f,P.get(),r,"qualification",0);for(const auto&config:configs()){auto out=calculate(w,config,plans,false);require(out.value.total==0,"untimed full cold path");++cases;}if(input==1){w.expected="00";bool rejected=false;try{calculate(w,{"block-default",0},plans,false);}catch(const std::exception&e){rejected=std::string(e.what())=="block symmetric expected output";}require(rejected,"block cold altered output rejection");++bad;}}}std::cout<<"{\"full_block_cold_untimed_paths\":"<<cases<<",\"altered_expected_outputs_rejected\":"<<bad<<",\"timing_performed\":false}\n";}
static void bench_new(const std::string&directory,const std::string&plans,const std::string&protocol,const std::string&panel){require(directory=="research/cm-marked-scalar/fixtures-v2"&&plans=="research/cm-marked-scalar/residual-v1/plans.json"&&(panel=="calibration"||panel=="heldout"),"block cold paths and panel");admission();auto digest=frozen(protocol);auto p=read_json(protocol),data=read_json(p.at("execution").at("placement").at("point_manifest").str());std::set<std::string> names={"P-192","P-224","P-256","P-384","P-521"};std::set<std::pair<std::string,unsigned>> seen;std::vector<Work> work;unsigned count=panel=="calibration"?4:8;for(const auto&item:data.at("rows").array)if(item.at("panel").str()==panel){auto index=item.at("index").unsigned_integer();auto name=item.at("curve").str();require(index<count&&names.count(name)&&seen.emplace(name,unsigned(index)).second,"block finite workload");work.push_back({name,panel,item.at("request").str(),item.at("expected").str(),unsigned(index)});}require(work.size()==5*count,"block complete workload");auto configurations=configs();for(unsigned round=0;round<=6;++round){std::mt19937_64 random(0x43414348455632ULL+round+(panel=="heldout"?1009:0));std::shuffle(configurations.begin(),configurations.end(),random);for(const auto&w:work)for(const auto&config:configurations)std::cout<<canonical_json(row(w,config,round,calculate(w,config,plans,true),digest))<<'\n';}}
}
int main(int argc,char**argv){try{if(argc==4&&std::string(argv[1])=="--qualify"){blockcold::qualify_new(argv[2],argv[3]);return 0;}require(argc==6&&std::string(argv[1])=="--bench","block-eval --qualify FIXTURES PLANS | --bench FIXTURES PLANS PROTOCOL PANEL");blockcold::bench_new(argv[2],argv[3],argv[4],argv[5]);return 0;}catch(const std::exception&e){std::cerr<<"block cold refused/failed: "<<e.what()<<'\n';return 1;}}
